B.aVz=new A.bF(B.tE,"My Journey","/journey")
B.aVD=new A.bF(B.tK,"Family Wing","/academy/family")
B.St=new A.bF(B.hG,"Bookmarks","#bookmarks")
B.agw=new A.ad(62440,"MaterialIcons",null,!1)
